# How the engine moves a fighter by frame data (control.lua frame_velocity,
# animation.lua):
#  * dvx is re-applied as a speed floor and dvy is ADDED on every tick of the
#    frame (wait + 1 ticks) -- including ticks frozen by hit lag, so a frame with
#    both dvy and a hitbox launches higher every time it connects. Launch on a
#    frame without itr, and prefer absolute dvy (value > 500 sets vy = dvy - 550).
#  * entering frame 212 (jump) from a move re-runs the jump launch; end airborne
#    moves with next: 999, which the engine turns into a plain fall.
ABSOLUTE = 550
SWISH = 'data\\045.wav'           # LF2's sword-dash swish (Deep's D>J)
SWORD = 'data\\054.wav'           # LF2's sword-special sound (Deep's jump/dash sword)
SLASH = 'data\\008.wav'           # LF2's weapon-swing swish (object_data.lua also swaps Deep's punch sound for it)

PARRY_FRAMES = (241, 243)         # combat.lua: a hit here starts the counter at 245
COUNTER_FRAME = 245


def itr(x, y, w, h, dvx=0, dvy=0, fall=0, vrest=0, arest=0, bdefend=0, injury=0, effect=1, kind=0):
    return (f'   itr:\n      kind: {kind}  x: {x}  y: {y}  w: {w}  h: {h}  dvx: {dvx}  dvy: {dvy}  fall: {fall}'
            f'  vrest: {vrest}  arest: {arest}  bdefend: {bdefend}  injury: {injury}  effect: {effect}\n   itr_end:\n')


def bdy(x, y, w, h):
    return f'   bdy:\n      kind: 0  x: {x}  y: {y}  w: {w}  h: {h}\n   bdy_end:\n'


def frame(n, name, pic, state, wait, nxt, dvx=0, dvy=0, mp=0, body=True, extra='', hits=None, sound=None, cx=CX, cy=CY):
    head = f'   pic: {pic}  state: {state}  wait: {wait}  next: {nxt}  dvx: {dvx}  dvy: {dvy}  dvz: 0  centerx: {cx}  centery: {cy}'
    if mp:
        head += f'  mp: {mp}'
    if sound:
        head += f'  sound: {sound}'
    if hits:
        head += '  ' + '  '.join(f'hit_{k}: {v}' for k, v in hits.items())
    return f'<frame> {n} {name}\n{head}\n{extra}{bdy(*BODY) if body else ""}<frame_end>\n'


# Sword hitbox in front of the chest; a lunge reaches further.
def blade(reach=48, **kw):
    return itr(CX + 4, CY - 58, reach, 28, **kw)


LUNGE_CANCEL = {'Ua': 270}        # D^A during the lunge cancels it into the rising slash (pays its MP)
FLURRY_EXTRA_MP = 20              # each extra flurry round (press A during it)


def flurry_hit():
    # 14 per stab, a small push; fall 5 so the stun counter never reaches a knockdown
    return blade(54, dvx=3, fall=5, vrest=6, bdefend=12, injury=14)


def lunge_blade():
    # wider (starts at the chest, reaches 72 px) and taller (head to hips) than a
    # normal stab; vrest 4 = the same victim can be hit again every 5 ticks
    return itr(CX - 6, CY - 66, 78, 46, dvx=2, fall=14, vrest=4, bdefend=12, injury=11)


